27	/**
28	 * Rejects an {@link OwnerFieldsDto} whose required identity fields are missing or blank
29	 * (null, empty or whitespace-only). This complements the schema's bean-validation
30	 * constraints, which do not treat a whitespace-only address or city as invalid.
31	 */
32	public class OwnerFieldsValidator implements Validator {
33	
34	    private static final List<String> REQUIRED_FIELDS =
35	        List.of("firstName", "lastName", "address", "city", "telephone");
36	
37	    @Override
38	    public boolean supports(Class<?> clazz) {
39	        return OwnerFieldsDto.class.isAssignableFrom(clazz);
40	    }
41	
42	    @Override
43	    public void validate(Object target, Errors errors) {
44	        OwnerFieldsDto owner = (OwnerFieldsDto) target;
45	        owner.setAddress(AddressNormalizer.normalize(owner.getAddress()));
46	        for (String field : REQUIRED_FIELDS) {
47	            ValidationUtils.rejectIfEmptyOrWhitespace(errors, field, "required", "must not be blank");
48	        }
49	        String telephone = owner.getTelephone();
50	        String raw = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
51	        String e164 = raw.startsWith("+") ? raw
52	            : "+61" + (raw.startsWith("0") ? raw.substring(1) : raw);
53	        if (e164.substring(1).matches("\\d{8,15}")) {
54	            owner.setTelephone(e164);
55	        } else {
56	            errors.rejectValue("telephone", "telephone", "must be a valid E.164 telephone number");
57	        }
58	        String email = owner.getEmail();
59	        if (email != null) {
60	            owner.setEmail(email.toLowerCase(Locale.ROOT));
61	        }
62	    }
63	}
